"use client";

/**
 * A PIN Nubnb generated, shown once (Kian's ruling of 2026-10-13, evening:
 * PINs are generated by Nubnb, never chosen, and shown once): the six digits
 * large, in two groups of three, and the reminder that they will not be shown
 * again. Whatever is given as children (a dialog's line about it) sits under
 * the box at the box's own distance. The PIN lives only in the state of the
 * component showing it; nothing here keeps it.
 */

import type { ReactNode } from "react";
import styles from "./PinGate.module.css";

export function PinReveal({ pin, label, children }: { pin: string; label: string; children?: ReactNode }) {
  return (
    <div className={styles.revealGroup}>
      <div className={styles.reveal} role="group" aria-label={label}>
        <span className={styles.revealDigits} translate="no">
          {pin.slice(0, 3)}
          <span className={styles.revealGap} aria-hidden />
          {pin.slice(3)}
        </span>
        <span className={styles.revealNote}>Shown once: note it now.</span>
      </div>
      {children}
    </div>
  );
}
